/* ===== #368: restore from an app backup (.json) ===== */
/* Strict validation that a picked file is the app's own backup format
   (the JSON written by exportWorkoutData()/downloadWorkoutBackup()).
   PURE: parses and checks only — nothing is mutated before this passes.
   Returns {ok:true,data} or {ok:false,reason}. */
const OB_BACKUP_ARRAY_KEYS=['completed','templates','tags','exerciseTagPresets','archivedPrograms','savedPrograms','customExercises','favorites','restDays']; /* restDays is legacy-only (feature removed 2026-09-22): old backups still validate, but the key is ignored on restore — nothing reads it anymore. */
const OB_BACKUP_OBJECT_KEYS=['activeProgram','draft','savedBuilder','savedBuilderStash','progressionSetup','savedFilter','settingsSections','subscriptions','scalarRevs','favoriteStamps'];
const OB_BACKUP_STRING_KEYS=['dashboardPeriod','statsPeriod','logPeriod','emailSyncHash'];
