    '<br>'+escapeHtml(obBackupCountLine(s))+'.</div>'+
    '<div class="ob-imp-err">Restoring <strong>replaces all</strong> current data with this backup. A copy of your current data is kept: Settings \u2192 Data \u2192 Undo last restore, for 30 days.</div>';
